def count_black_squares(N):
    # Assuming (1, 1) is black, so i+j is even is black.
    black_count = 0
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            if (i + j) % 2 == 0:
                black_count += 1
    return black_count

print(f"N=5: {count_black_squares(5)}")
print(f"N=7: {count_black_squares(7)}")
print(f"N=2025: {count_black_squares(2025)}")
